window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a53fe1bf9ebbdd17"]={"versions": [{"id": "FIG-a53fe1bf9ebbdd17", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm).\n</li><li><strong>Funktionaler Kontext:</strong> Spezifiziert in <code>AUTOSAR_TPS_SoftwareComponentTemplate</code> (Kapitel 5: <em>Internal Behavior</em>, Abschnitt Parametrierung/Kalibrierung).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des Zugriffs einer <code>RunnableEntity</code> auf Kalibrierparameter (<code>ParameterAccess</code>) unter Verwendung geteilter Stützstellenachsen (<em>Grouped Axes</em> bzw. <code>SwAxisGrouped</code>). Ermöglicht die formale Entkopplung und Referenzierung gemeinsamer Achsenstützstellen (<code>AXIS_PTS</code>) für Kennlinien (<code>CURVE</code>) und Kennfelder (<code>MAP</code>) im AUTOSAR-Parametermodell sowie die Übergabe dieser Metadaten an die RTE- und A2L/ASAM-MCD-2-MC-Generierung.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ParameterAccess</code></strong> (Spezialisierung von <code>AbstractAccessPoint</code>, <code>AtpStructureElement</code>, <code>Identifiable</code>):\n Modelliert den formalen Lesezugriff eines Runnables auf einen Parameter (Port-Parameter oder lokaler Parameter).\n</li><li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):\n Eigenschaftscontainer für softwaretechnische Datendefinitionen; unterstützt AUTOSAR-Systemvariabilität über Post-Build- oder Bind-Time-Kriterien.\n</li><li><strong><code>SwCalprmAxisSet</code></strong>:\n Aggregiert sämtliche Achsendefinitionen (<code>SwCalprmAxis</code>), die zu einem zusammengesetzten Kalibrierobjekt (z. B. 2D/3D-Kennfeld) gehören.\n</li><li><strong><code>SwCalprmAxis</code></strong>:\n Repräsentiert eine einzelne Dimension/Achse.\n <em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>category: CalprmAxisCategoryEnum [0..1]</code> (z. B. <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>GROUPED</code>)\n</li><li><code>displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>swAxisIndex: AxisIndexType [0..1]</code> (Achsenindex, z. B. 1 für X-Achse, 2 für Y-Achse)\n</li><li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwCalprmAxisTypeProps</code></strong> (abstrakte Basisklasse):\n Enthält physikalische und mathematische Randeigenschaften der Achse.\n <em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>maxGradient: Float [0..1]</code>\n</li><li><code>monotony: MonotonyEnum [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwAxisGrouped</code></strong> (Generalisierung von <code>SwCalprmAxisTypeProps</code>):\n Spezialisierung für Gruppenachsen; verknüpft die Achse mit einem eigenständigen Parameterobjekt.\n <em>Attribut:</em>\n<ul class=\"fig-list\"><li><code>swAxisIndex: AxisIndexType [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwCalprmRefProxy</code></strong>:\n Proxy-Element zur Entkopplung und Auflösung paketübergreifender Parameterreferenzen im Modell.\n</li><li><strong><code>AutosarParameterRef</code></strong> (im Scope <em>Selection of DataPrototype</em>):\n Adapter zur typisierten Referenzierung eines Zielparameters.\n</li><li><strong><code>DataPrototype</code></strong> (Spezialisierung von <code>AtpPrototype</code>):\n Das eigentliche Datum im Komponentenmodell (<code>ParameterDataPrototype</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>ParameterAccess</code> → <code>SwDataDefProps</code>:</strong> Komposition <code>+swDataDefProps</code> [<code>0..1</code>], annotiert mit <code>«atpSplitable»</code> (erlaubt Verteilung über mehrere ARXML-Fragmente).\n</li><li><strong><code>ParameterAccess</code> → <code>AutosarParameterRef</code>:</strong> Komposition <code>+accessedParameter</code> [<code>0..1</code>] (referenziert den primären Kennfeld-/Kurvenparameter).\n</li><li><strong><code>SwDataDefProps</code> → <code>SwCalprmAxisSet</code>:</strong> Komposition <code>+swCalprmAxisSet</code> [<code>0..1</code>].\n</li><li><strong><code>SwCalprmAxisSet</code> → <code>SwCalprmAxis</code>:</strong> Komposition <code>+swCalprmAxis</code> [<code>0..*</code>].\n</li><li><strong><code>SwCalprmAxis</code> → <code>SwCalprmAxisTypeProps</code>:</strong> Komposition <code>+swCalprmAxisTypeProps</code> [<code>0..1</code>].\n</li><li><strong><code>SwAxisGrouped</code> → <code>SwCalprmAxisTypeProps</code>:</strong> Vererbung (Is-A-Beziehung).\n</li><li><strong><code>SwAxisGrouped</code> → <code>SwCalprmRefProxy</code>:</strong> Komposition <code>+swCalprmRef</code> [<code>1</code>] (strikte 1:1-Existenzabhängigkeit für Gruppenachsen).\n</li><li><strong><code>SwCalprmRefProxy</code> → <code>AutosarParameterRef</code>:</strong> Komposition <code>+arParameter</code> [<code>0..1</code>].\n</li><li><strong><code>AutosarParameterRef</code> → <code>DataPrototype</code>:</strong>\n<ul class=\"fig-list\"><li>Lokaler Zugriff: Direkte gerichtete Assoziation <code>+localParameter</code> [<code>0..1</code>] (Komponenten-interne Kalibrierdaten).\n</li><li>Instanziierter Zugriff: Gerichtete Assoziation <code>+autosarParameter</code> [<code>0..1</code>] mit Stereotyp <code>«instanceRef»</code> (Port-basierter Parameter über Komponentengrenzen hinweg).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (semantische Auflösung)</h4>\n<p class=\"fig-p\">Als M2-Metamodell-Strukturdiagramm existiert keine Laufzeit-Dynamik im Sinne von Callbacks oder Zustandsübergängen. Das Diagramm definiert stattdessen den semantischen Auflösungspfad für Toolchains und Generatoren:</p>\n<pre class=\"fig-pre\"><code>[Runnable: ParameterAccess] \n       │ \n       ├─► +accessedParameter ────► [AutosarParameterRef] ──► [DataPrototype: Kennfeld/Werte]\n       │\n       └─► +swDataDefProps ───────► [SwCalprmAxisSet] \n                                          │\n                                          └─► [SwCalprmAxis (Index n)]\n                                                    │\n                                                    └─► [SwAxisGrouped]\n                                                              │\n                                                              └─► +swCalprmRef [1] \n                                                                        │\n                                                                        └─► [SwCalprmRefProxy]\n                                                                                  │\n                                                                                  └─► [AutosarParameterRef]\n                                                                                            │\n                                                                                            ├─► localParameter (intern)\n                                                                                            └─► autosarParameter («instanceRef», Port)</code></pre>\n<ol class=\"fig-list\"><li><strong>Parameteridentifikation:</strong> Identifikation des Hauptdatenwerts (z. B. Stützwerte einer Look-Up-Tabelle) via <code>accessedParameter</code>.\n</li><li><strong>Achsen-Parsing:</strong> Traversierung über <code>swDataDefProps/swCalprmAxisSet/swCalprmAxis</code> zur Ermittlung der Dimensionen (<code>swAxisIndex</code>).\n</li><li><strong>Gruppenachsen-Indirektion:</strong> Bei <code>category == GROUPED</code> instanziiert das Modell zwingend <code>SwAxisGrouped</code>. Über <code>SwCalprmRefProxy</code> wird die Achsenquelle aufgelöst:\n<ul class=\"fig-list\"><li>Ist <code>localParameter</code> gesetzt: Auflösung auf internen <code>ParameterDataPrototype</code> der SWC.\n</li><li>Ist <code>autosarParameter</code> gesetzt: Kontextuelle Instanzauflösung via <code>«instanceRef»</code> auf ein <code>ParameterDataPrototype</code> eines <code>ParameterPort</code> (<code>RPortPrototype</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Speicher- und ROM-Optimierung:</strong> Ermöglicht das Teilen identischer Stützstellenvektoren (<code>AXIS_PTS</code>) zwischen mehreren Kennlinien/Kennfeldern zur Reduktion des ROM-Bedarfs im Steuergerät.\n</li><li><strong>A2L- / ASAM MCD-2 MC-Export:</strong> A2L-Generatoren nutzen diesen Pfad zwingend, um im Kalibrierfile für ein <code>CHARACTERISTIC</code> des Typs <code>MAP</code>/<code>CUBOID</code> einen <code>AXIS_DESCR</code> mit Verweis auf das separate <code>AXIS_PTS</code>-Objekt zu generieren (Referenz via <code>AXIS_PTS_REF</code>). Fehlt <code>SwCalprmRefProxy</code>, ist die A2L inkonsistent.\n</li><li><strong>RTE-API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf die Achswerte erfolgt nicht implizit über den Kennfeldzugriff, sondern muss im SWC-Code separat über die vom RTE-Generator bereitgestellten Makros bzw. Funktionssignaturen bedient werden (z. B. <code>Rte_Prm_&lt;Port&gt;_&lt;Param&gt;()</code> bzw. Zugriff auf kalibrierbare ROM-Symbole).\n</li><li>Wenn <code>ParameterAccess</code> Achseneigenschaften über <code>swDataDefProps</code> überschreibt, muss der RTE-Generator sicherstellen, dass Konsistenz zu den Typdefinitionen (<code>ApplicationPrimitiveDataType</code> / <code>ImplementationDataType</code>) gewahrt bleibt.\n</li></ul>\n</li><li><strong>Modellierungs-Constraint:</strong> Da die Multiplizität von <code>+swCalprmRef</code> exakt <code>1</code> beträgt, darf eine als <code>SwAxisGrouped</code> typisierte Achse im XML/ARXML niemals ohne gültigen Proxy auf einen konkreten Stützstellen-<code>DataPrototype</code> belassen werden.\n</li></ul>"}, {"id": "FIG-ed55750d8c5a5ebf", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm).\n</li><li><strong>Funktionaler Kontext:</strong> Spezifiziert in <code>AUTOSAR_TPS_SoftwareComponentTemplate</code> (Kapitel 5: <em>Internal Behavior</em>, Abschnitt Parametrierung/Kalibrierung).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des Zugriffs einer <code>RunnableEntity</code> auf Kalibrierparameter (<code>ParameterAccess</code>) unter Verwendung geteilter Stützstellenachsen (<em>Grouped Axes</em> bzw. <code>SwAxisGrouped</code>). Ermöglicht die formale Entkopplung und Referenzierung gemeinsamer Achsenstützstellen (<code>AXIS_PTS</code>) für Kennlinien (<code>CURVE</code>) und Kennfelder (<code>MAP</code>) im AUTOSAR-Parametermodell sowie die Übergabe dieser Metadaten an die RTE- und A2L/ASAM-MCD-2-MC-Generierung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ParameterAccess</code></strong> (Spezialisierung von <code>AbstractAccessPoint</code>, <code>AtpStructureElement</code>, <code>Identifiable</code>):\n Modelliert den formalen Lesezugriff eines Runnables auf einen Parameter (Port-Parameter oder lokaler Parameter).\n</li><li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):\n Eigenschaftscontainer für softwaretechnische Datendefinitionen; unterstützt AUTOSAR-Systemvariabilität über Post-Build- oder Bind-Time-Kriterien.\n</li><li><strong><code>SwCalprmAxisSet</code></strong>:\n Aggregiert sämtliche Achsendefinitionen (<code>SwCalprmAxis</code>), die zu einem zusammengesetzten Kalibrierobjekt (z. B. 2D/3D-Kennfeld) gehören.\n</li><li><strong><code>SwCalprmAxis</code></strong>:\n Repräsentiert eine einzelne Dimension/Achse.\n <em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>category: CalprmAxisCategoryEnum [0..1]</code> (z. B. <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>GROUPED</code>)\n</li><li><code>displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>swAxisIndex: AxisIndexType [0..1]</code> (Achsenindex, z. B. 1 für X-Achse, 2 für Y-Achse)\n</li><li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwCalprmAxisTypeProps</code></strong> (abstrakte Basisklasse):\n Enthält physikalische und mathematische Randeigenschaften der Achse.\n <em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>maxGradient: Float [0..1]</code>\n</li><li><code>monotony: MonotonyEnum [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwAxisGrouped</code></strong> (Generalisierung von <code>SwCalprmAxisTypeProps</code>):\n Spezialisierung für Gruppenachsen; verknüpft die Achse mit einem eigenständigen Parameterobjekt.\n <em>Attribut:</em>\n<ul class=\"fig-list\"><li><code>swAxisIndex: AxisIndexType [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwCalprmRefProxy</code></strong>:\n Proxy-Element zur Entkopplung und Auflösung paketübergreifender Parameterreferenzen im Modell.\n</li><li><strong><code>AutosarParameterRef</code></strong> (im Scope <em>Selection of DataPrototype</em>):\n Adapter zur typisierten Referenzierung eines Zielparameters.\n</li><li><strong><code>DataPrototype</code></strong> (Spezialisierung von <code>AtpPrototype</code>):\n Das eigentliche Datum im Komponentenmodell (<code>ParameterDataPrototype</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>ParameterAccess</code> → <code>SwDataDefProps</code>:</strong> Komposition <code>+swDataDefProps</code> [<code>0..1</code>], annotiert mit <code>«atpSplitable»</code> (erlaubt Verteilung über mehrere ARXML-Fragmente).\n</li><li><strong><code>ParameterAccess</code> → <code>AutosarParameterRef</code>:</strong> Komposition <code>+accessedParameter</code> [<code>0..1</code>] (referenziert den primären Kennfeld-/Kurvenparameter).\n</li><li><strong><code>SwDataDefProps</code> → <code>SwCalprmAxisSet</code>:</strong> Komposition <code>+swCalprmAxisSet</code> [<code>0..1</code>].\n</li><li><strong><code>SwCalprmAxisSet</code> → <code>SwCalprmAxis</code>:</strong> Komposition <code>+swCalprmAxis</code> [<code>0..*</code>].\n</li><li><strong><code>SwCalprmAxis</code> → <code>SwCalprmAxisTypeProps</code>:</strong> Komposition <code>+swCalprmAxisTypeProps</code> [<code>0..1</code>].\n</li><li><strong><code>SwAxisGrouped</code> → <code>SwCalprmAxisTypeProps</code>:</strong> Vererbung (Is-A-Beziehung).\n</li><li><strong><code>SwAxisGrouped</code> → <code>SwCalprmRefProxy</code>:</strong> Komposition <code>+swCalprmRef</code> [<code>1</code>] (strikte 1:1-Existenzabhängigkeit; eine Notiz stellt klar: <em>„This aggregation cannot be set to 0..1 based on the non-mainstream schema generation instructions defined at the aggregation.“</em>).\n</li><li><strong><code>SwCalprmRefProxy</code> → <code>AutosarParameterRef</code>:</strong> Komposition <code>+arParameter</code> [<code>0..1</code>].\n</li><li><strong><code>AutosarParameterRef</code> → <code>DataPrototype</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+localParameter</code> [<code>0..1</code>] (Verweis auf komponenteninterne Parameter).\n</li><li>Assoziation <code>+autosarParameter</code> [<code>0..1</code>] mit Stereotyp <code>«instanceRef»</code> (kontextualisierte Instanzreferenz auf Softwarekomponenten-Parameter an Ports).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als M2-Metamodell-Strukturdiagramm existiert keine Laufzeit-Dynamik im Sinne von Callbacks oder Zustandsübergängen. Das Diagramm definiert stattdessen den semantischen Auflösungspfad für Toolchains und Generatoren:</p>\n<pre class=\"fig-pre\"><code>[Runnable: ParameterAccess] \n       │ \n       ├─► +accessedParameter ────► [AutosarParameterRef] ──► [DataPrototype: Kennfeld/Werte]\n       │\n       └─► +swDataDefProps ───────► [SwCalprmAxisSet] \n                                          │\n                                          └─► [SwCalprmAxis (Index n)]\n                                                    │\n                                                    └─► [SwAxisGrouped]\n                                                              │\n                                                              └─► +swCalprmRef [1] \n                                                                        │\n                                                                        └─► [SwCalprmRefProxy]\n                                                                                  │\n                                                                                  └─► [AutosarParameterRef]\n                                                                                            │\n                                                                                            ├─► localParameter (intern)\n                                                                                            └─► autosarParameter («instanceRef», Port)</code></pre>\n<ol class=\"fig-list\"><li><strong>Parameteridentifikation:</strong> Identifikation des Hauptdatenwerts (z. B. Stützwerte einer Look-Up-Tabelle) via <code>accessedParameter</code>.\n</li><li><strong>Achsen-Parsing:</strong> Traversierung über <code>swDataDefProps/swCalprmAxisSet/swCalprmAxis</code> zur Ermittlung der Dimensionen (<code>swAxisIndex</code>).\n</li><li><strong>Gruppenachsen-Indirektion:</strong> Bei <code>category == GROUPED</code> instanziiert das Modell zwingend <code>SwAxisGrouped</code>. Über <code>SwCalprmRefProxy</code> wird die Achsenquelle aufgelöst:\n<ul class=\"fig-list\"><li>Ist <code>localParameter</code> gesetzt: Auflösung auf internen <code>ParameterDataPrototype</code> der SWC.\n</li><li>Ist <code>autosarParameter</code> gesetzt: Kontextuelle Instanzauflösung via <code>«instanceRef»</code> auf ein <code>ParameterDataPrototype</code> eines <code>ParameterPort</code> (<code>RPortPrototype</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Speicher- und ROM-Optimierung:</strong> Ermöglicht das Teilen identischer Stützstellenvektoren (<code>AXIS_PTS</code>) zwischen mehreren Kennlinien/Kennfeldern zur Reduktion des ROM-Bedarfs im Steuergerät.\n</li><li><strong>A2L- / ASAM MCD-2 MC-Export:</strong> A2L-Generatoren nutzen diesen Pfad zwingend, um im Kalibrierfile für ein <code>CHARACTERISTIC</code> des Typs <code>MAP</code>/<code>CUBOID</code> einen <code>AXIS_DESCR</code> mit Verweis auf das separate <code>AXIS_PTS</code>-Objekt zu generieren (Referenz via <code>AXIS_PTS_REF</code>). Fehlt <code>SwCalprmRefProxy</code>, ist die A2L inkonsistent.\n</li><li><strong>RTE-API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf die Achswerte erfolgt nicht implizit über den Kennfeldzugriff, sondern muss im SWC-Code separat über die vom RTE-Generator bereitgestellten Makros bzw. Funktionssignaturen bedient werden (z. B. <code>Rte_Prm_&lt;Port&gt;_&lt;Param&gt;()</code> bzw. Zugriff auf kalibrierbare ROM-Symbole).\n</li><li>Wenn <code>ParameterAccess</code> Achseneigenschaften über <code>swDataDefProps</code> überschreibt, muss der RTE-Generator sicherstellen, dass Konsistenz zu den Typdefinitionen (<code>ApplicationPrimitiveDataType</code> / <code>ImplementationDataType</code>) gewahrt bleibt.\n</li></ul>\n</li><li><strong>Modellierungs-Constraint:</strong> Da die Multiplizität von <code>+swCalprmRef</code> exakt <code>1</code> beträgt, darf eine als <code>SwAxisGrouped</code> typisierte Achse im XML/ARXML niemals ohne gültigen Proxy auf einen konkreten Stützstellen-<code>DataPrototype</code> belassen werden.\n</li></ul>"}, {"id": "FIG-a1724be6c3cdf4c5", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm).\n</li><li><strong>Funktionaler Kontext:</strong> Spezifiziert in <code>AUTOSAR_TPS_SoftwareComponentTemplate</code> (Kapitel 5: <em>Internal Behavior</em>, Abschnitt Parametrierung/Kalibrierung).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des Zugriffs einer <code>RunnableEntity</code> auf Kalibrierparameter (<code>ParameterAccess</code>) unter Verwendung geteilter Stützstellenachsen (<em>Grouped Axes</em> bzw. <code>SwAxisGrouped</code>). Ermöglicht die formale Entkopplung und Referenzierung gemeinsamer Achsenstützstellen (<code>AXIS_PTS</code>) für Kennlinien (<code>CURVE</code>) und Kennfelder (<code>MAP</code>) im AUTOSAR-Parametermodell sowie die Übergabe dieser Metadaten an die RTE- und A2L/ASAM-MCD-2-MC-Generierung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ParameterAccess</code></strong> (Spezialisierung von <code>AbstractAccessPoint</code>, <code>AtpStructureElement</code>, <code>Identifiable</code>):\n Modelliert den formalen Lesezugriff eines Runnables auf einen Parameter (Port-Parameter oder lokaler Parameter).\n</li><li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):\n Eigenschaftscontainer für softwaretechnische Datendefinitionen; unterstützt AUTOSAR-Systemvariabilität über Post-Build- oder Bind-Time-Kriterien.\n</li><li><strong><code>SwCalprmAxisSet</code></strong>:\n Aggregiert sämtliche Achsendefinitionen (<code>SwCalprmAxis</code>), die zu einem zusammengesetzten Kalibrierobjekt (z. B. 2D/3D-Kennfeld) gehören.\n</li><li><strong><code>SwCalprmAxis</code></strong>:\n Repräsentiert eine einzelne Dimension/Achse.\n <em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>category: CalprmAxisCategoryEnum [0..1]</code> (z. B. <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>GROUPED</code>)\n</li><li><code>displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>swAxisIndex: AxisIndexType [0..1]</code> (Achsenindex, z. B. 1 für X-Achse, 2 für Y-Achse)\n</li><li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwCalprmAxisTypeProps</code></strong> (abstrakte Basisklasse):\n Enthält physikalische und mathematische Randeigenschaften der Achse.\n <em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>maxGradient: Float [0..1]</code>\n</li><li><code>monotony: MonotonyEnum [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwAxisGrouped</code></strong> (Generalisierung von <code>SwCalprmAxisTypeProps</code>):\n Spezialisierung für Gruppenachsen; verknüpft die Achse mit einem eigenständigen Parameterobjekt.\n <em>Attribut:</em>\n<ul class=\"fig-list\"><li><code>swAxisIndex: AxisIndexType [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwCalprmRefProxy</code></strong>:\n Proxy-Element zur Entkopplung und Auflösung paketübergreifender Parameterreferenzen im Modell.\n</li><li><strong><code>AutosarParameterRef</code></strong> (im Scope <em>Selection of DataPrototype</em>):\n Adapter zur typisierten Referenzierung eines Zielparameters.\n</li><li><strong><code>DataPrototype</code></strong> (Spezialisierung von <code>AtpPrototype</code>):\n Das eigentliche Datum im Komponentenmodell (<code>ParameterDataPrototype</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>ParameterAccess</code> → <code>SwDataDefProps</code>:</strong> Komposition <code>+swDataDefProps</code> [<code>0..1</code>] mit Eigenschaft <code>{redefines swDataDefProps}</code>, annotiert mit <code>«atpSplitable»</code>.\n</li><li><strong><code>ParameterAccess</code> → <code>AutosarParameterRef</code>:</strong> Komposition <code>+accessedParameter</code> [<code>0..1</code>] (referenziert den primären Kennfeld-/Kurvenparameter).\n</li><li><strong><code>SwDataDefProps</code> → <code>SwCalprmAxisSet</code>:</strong> Komposition <code>+swCalprmAxisSet</code> [<code>0..1</code>].\n</li><li><strong><code>SwCalprmAxisSet</code> → <code>SwCalprmAxis</code>:</strong> Komposition <code>+swCalprmAxis</code> [<code>0..*</code>].\n</li><li><strong><code>SwCalprmAxis</code> → <code>SwCalprmAxisTypeProps</code>:</strong> Komposition <code>+swCalprmAxisTypeProps</code> [<code>0..1</code>].\n</li><li><strong><code>SwAxisGrouped</code> → <code>SwCalprmAxisTypeProps</code>:</strong> Vererbung (Is-A-Beziehung).\n</li><li><strong><code>SwAxisGrouped</code> → <code>SwCalprmRefProxy</code>:</strong> Komposition <code>+swCalprmRef</code> [<code>1</code>] (strikte 1:1-Existenzabhängigkeit; eine Notiz stellt klar: <em>„This aggregation cannot be set to 0..1 based on the non-mainstream schema generation instructions defined at the aggregation.“</em>).\n</li><li><strong><code>SwCalprmRefProxy</code> → <code>AutosarParameterRef</code>:</strong> Komposition <code>+arParameter</code> [<code>0..1</code>].\n</li><li><strong><code>AutosarParameterRef</code> → <code>DataPrototype</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+localParameter</code> [<code>0..1</code>] (Verweis auf komponenteninterne Parameter).\n</li><li>Assoziation <code>+autosarParameter</code> [<code>0..1</code>] mit Stereotyp <code>«instanceRef»</code> (kontextualisierte Instanzreferenz auf Softwarekomponenten-Parameter an Ports).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als M2-Metamodell-Strukturdiagramm existiert keine Laufzeit-Dynamik im Sinne von Callbacks oder Zustandsübergängen. Das Diagramm definiert stattdessen den semantischen Auflösungspfad für Toolchains und Generatoren:</p>\n<pre class=\"fig-pre\"><code>[Runnable: ParameterAccess] \n       │ \n       ├─► +accessedParameter ────► [AutosarParameterRef] ──► [DataPrototype: Kennfeld/Werte]\n       │\n       └─► +swDataDefProps ───────► [SwCalprmAxisSet] \n                                          │\n                                          └─► [SwCalprmAxis (Index n)]\n                                                    │\n                                                    └─► [SwAxisGrouped]\n                                                              │\n                                                              └─► +swCalprmRef [1] \n                                                                        │\n                                                                        └─► [SwCalprmRefProxy]\n                                                                                  │\n                                                                                  └─► [AutosarParameterRef]\n                                                                                            │\n                                                                                            ├─► localParameter (intern)\n                                                                                            └─► autosarParameter («instanceRef», Port)</code></pre>\n<ol class=\"fig-list\"><li><strong>Parameteridentifikation:</strong> Identifikation des Hauptdatenwerts (z. B. Stützwerte einer Look-Up-Tabelle) via <code>accessedParameter</code>.\n</li><li><strong>Achsen-Parsing:</strong> Traversierung über <code>swDataDefProps/swCalprmAxisSet/swCalprmAxis</code> zur Ermittlung der Dimensionen (<code>swAxisIndex</code>).\n</li><li><strong>Gruppenachsen-Indirektion:</strong> Bei <code>category == GROUPED</code> instanziiert das Modell zwingend <code>SwAxisGrouped</code>. Über <code>SwCalprmRefProxy</code> wird die Achsenquelle aufgelöst:\n<ul class=\"fig-list\"><li>Ist <code>localParameter</code> gesetzt: Auflösung auf internen <code>ParameterDataPrototype</code> der SWC.\n</li><li>Ist <code>autosarParameter</code> gesetzt: Kontextuelle Instanzauflösung via <code>«instanceRef»</code> auf ein <code>ParameterDataPrototype</code> eines <code>ParameterPort</code> (<code>RPortPrototype</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Speicher- und ROM-Optimierung:</strong> Ermöglicht das Teilen identischer Stützstellenvektoren (<code>AXIS_PTS</code>) zwischen mehreren Kennlinien/Kennfeldern zur Reduktion des ROM-Bedarfs im Steuergerät.\n</li><li><strong>A2L- / ASAM MCD-2 MC-Export:</strong> A2L-Generatoren nutzen diesen Pfad zwingend, um im Kalibrierfile für ein <code>CHARACTERISTIC</code> des Typs <code>MAP</code>/<code>CUBOID</code> einen <code>AXIS_DESCR</code> mit Verweis auf das separate <code>AXIS_PTS</code>-Objekt zu generieren (Referenz via <code>AXIS_PTS_REF</code>). Fehlt <code>SwCalprmRefProxy</code>, ist die A2L inkonsistent.\n</li><li><strong>RTE-API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf die Achswerte erfolgt nicht implizit über den Kennfeldzugriff, sondern muss im SWC-Code separat über die vom RTE-Generator bereitgestellten Makros bzw. Funktionssignaturen bedient werden (z. B. <code>Rte_Prm_&lt;Port&gt;_&lt;Param&gt;()</code> bzw. Zugriff auf kalibrierbare ROM-Symbole).\n</li><li>Wenn <code>ParameterAccess</code> Achseneigenschaften über <code>swDataDefProps</code> überschreibt, muss der RTE-Generator sicherstellen, dass Konsistenz zu den Typdefinitionen (<code>ApplicationPrimitiveDataType</code> / <code>ImplementationDataType</code>) gewahrt bleibt.\n</li></ul>\n</li><li><strong>Modellierungs-Constraint:</strong> Da die Multiplizität von <code>+swCalprmRef</code> exakt <code>1</code> beträgt, darf eine als <code>SwAxisGrouped</code> typisierte Achse im XML/ARXML niemals ohne gültigen Proxy auf einen konkreten Stützstellen-<code>DataPrototype</code> belassen werden.\n</li></ul>"}, {"id": "FIG-865b6a22e24bd8ca", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Ausschnitt (UML-Klassendiagramm).\n</li><li><strong>Funktionaler Kontext:</strong> Spezifiziert in <code>AUTOSAR_TPS_SoftwareComponentTemplate</code> (Kapitel 5: <em>Internal Behavior</em>, Abschnitt Parametrierung/Kalibrierung).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des Zugriffs einer <code>RunnableEntity</code> auf Kalibrierparameter (<code>ParameterAccess</code>) unter Verwendung geteilter Stützstellenachsen (<em>Grouped Axes</em> bzw. <code>SwAxisGrouped</code>). Ermöglicht die formale Entkopplung und Referenzierung gemeinsamer Achsenstützstellen (<code>AXIS_PTS</code>) für Kennlinien (<code>CURVE</code>) und Kennfelder (<code>MAP</code>) im AUTOSAR-Parametermodell sowie die Übergabe dieser Metadaten an die RTE- und A2L/ASAM-MCD-2-MC-Generierung.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>ParameterAccess</code></strong> (Spezialisierung von <code>AbstractAccessPoint</code>, <code>AtpStructureElement</code>, <code>Identifiable</code>):\n Modelliert den formalen Lesezugriff eines Runnables auf einen Parameter (Port-Parameter oder lokaler Parameter).\n</li><li><strong><code>SwDataDefProps</code></strong> (<code>«atpVariation»</code>):\n Eigenschaftscontainer für softwaretechnische Datendefinitionen; unterstützt AUTOSAR-Systemvariabilität über Post-Build- oder Bind-Time-Kriterien.\n</li><li><strong><code>SwCalprmAxisSet</code></strong>:\n Aggregiert sämtliche Achsendefinitionen (<code>SwCalprmAxis</code>), die zu einem zusammengesetzten Kalibrierobjekt (z. B. 2D/3D-Kennfeld) gehören.\n</li><li><strong><code>SwCalprmAxis</code></strong>:\n Repräsentiert eine einzelne Dimension/Achse.\n <em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>category: CalprmAxisCategoryEnum [0..1]</code> (z. B. <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>GROUPED</code>)\n</li><li><code>displayFormat: DisplayFormatString [0..1]</code>\n</li><li><code>swAxisIndex: AxisIndexType [0..1]</code> (Achsenindex, z. B. 1 für X-Achse, 2 für Y-Achse)\n</li><li><code>swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwCalprmAxisTypeProps</code></strong> (abstrakte Basisklasse):\n Enthält physikalische und mathematische Randeigenschaften der Achse.\n <em>Attribute:</em>\n<ul class=\"fig-list\"><li><code>maxGradient: Float [0..1]</code>\n</li><li><code>monotony: MonotonyEnum [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwAxisGrouped</code></strong> (Generalisierung von <code>SwCalprmAxisTypeProps</code>):\n Spezialisierung für Gruppenachsen; verknüpft die Achse mit einem eigenständigen Parameterobjekt.\n <em>Attribut:</em>\n<ul class=\"fig-list\"><li><code>swAxisIndex: AxisIndexType [0..1]</code>\n</li></ul>\n</li><li><strong><code>SwCalprmRefProxy</code></strong>:\n Proxy-Element zur Entkopplung und Auflösung paketübergreifender Parameterreferenzen im Modell.\n</li><li><strong><code>AutosarParameterRef</code></strong> (im Scope <em>Selection of DataPrototype</em>):\n Adapter zur typisierten Referenzierung eines Zielparameters.\n</li><li><strong><code>DataPrototype</code></strong> (Spezialisierung von <code>AtpPrototype</code>):\n Das eigentliche Datum im Komponentenmodell (<code>ParameterDataPrototype</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>ParameterAccess</code> → <code>SwDataDefProps</code>:</strong> Komposition <code>+swDataDefProps</code> [<code>0..1</code>] mit Eigenschaft <code>{redefines swDataDefProps}</code>, annotiert mit <code>«atpSplitable»</code>.\n</li><li><strong><code>ParameterAccess</code> → <code>AutosarParameterRef</code>:</strong> Komposition <code>+accessedParameter</code> [<code>0..1</code>] (referenziert den primären Kennfeld-/Kurvenparameter).\n</li><li><strong><code>SwDataDefProps</code> → <code>SwCalprmAxisSet</code>:</strong> Komposition <code>+swCalprmAxisSet</code> [<code>0..1</code>].\n</li><li><strong><code>SwCalprmAxisSet</code> → <code>SwCalprmAxis</code>:</strong> Komposition <code>+swCalprmAxis</code> [<code>0..*</code>].\n</li><li><strong><code>SwCalprmAxis</code> → <code>SwCalprmAxisTypeProps</code>:</strong> Komposition <code>+swCalprmAxisTypeProps</code> [<code>0..1</code>].\n</li><li><strong><code>SwAxisGrouped</code> → <code>SwCalprmAxisTypeProps</code>:</strong> Vererbung (Is-A-Beziehung).\n</li><li><strong><code>SwAxisGrouped</code> → <code>SwCalprmRefProxy</code>:</strong> Komposition <code>+swCalprmRef</code> [<code>1</code>] (strikte 1:1-Existenzabhängigkeit; eine Notiz stellt klar: <em>„This aggregation cannot be set to 0..1 based on the non-mainstream schema generation instructions defined at the aggregation.“</em>).\n</li><li><strong><code>SwCalprmRefProxy</code> → <code>AutosarParameterRef</code>:</strong> Komposition <code>+arParameter</code> [<code>0..1</code>].\n</li><li><strong><code>AutosarParameterRef</code> → <code>DataPrototype</code>:</strong>\n<ul class=\"fig-list\"><li>Assoziation <code>+localParameter</code> [<code>0..1</code>] (Verweis auf komponenteninterne Parameter).\n</li><li>Assoziation <code>+autosarParameter</code> [<code>0..1</code>] mit Stereotyp <code>«instanceRef»</code> (kontextualisierte Instanzreferenz auf Softwarekomponenten-Parameter an Ports).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als M2-Metamodell-Strukturdiagramm existiert keine Laufzeit-Dynamik im Sinne von Callbacks oder Zustandsübergängen. Das Diagramm definiert stattdessen den semantischen Auflösungspfad für Toolchains und Generatoren:</p>\n<pre class=\"fig-pre\"><code>[Runnable: ParameterAccess] \n       │ \n       ├─► +accessedParameter ────► [AutosarParameterRef] ──► [DataPrototype: Kennfeld/Werte]\n       │\n       └─► +swDataDefProps ───────► [SwCalprmAxisSet] \n                                          │\n                                          └─► [SwCalprmAxis (Index n)]\n                                                    │\n                                                    └─► [SwAxisGrouped]\n                                                              │\n                                                              └─► +swCalprmRef [1] \n                                                                        │\n                                                                        └─► [SwCalprmRefProxy]\n                                                                                  │\n                                                                                  └─► [AutosarParameterRef]\n                                                                                            │\n                                                                                            ├─► localParameter (intern)\n                                                                                            └─► autosarParameter («instanceRef», Port)</code></pre>\n<ol class=\"fig-list\"><li><strong>Parameteridentifikation:</strong> Identifikation des Hauptdatenwerts (z. B. Stützwerte einer Look-Up-Tabelle) via <code>accessedParameter</code>.\n</li><li><strong>Achsen-Parsing:</strong> Traversierung über <code>swDataDefProps/swCalprmAxisSet/swCalprmAxis</code> zur Ermittlung der Dimensionen (<code>swAxisIndex</code>).\n</li><li><strong>Gruppenachsen-Indirektion:</strong> Bei <code>category == GROUPED</code> instanziiert das Modell zwingend <code>SwAxisGrouped</code>. Über <code>SwCalprmRefProxy</code> wird die Achsenquelle aufgelöst:\n<ul class=\"fig-list\"><li>Ist <code>localParameter</code> gesetzt: Auflösung auf internen <code>ParameterDataPrototype</code> der SWC.\n</li><li>Ist <code>autosarParameter</code> gesetzt: Kontextuelle Instanzauflösung via <code>«instanceRef»</code> auf ein <code>ParameterDataPrototype</code> eines <code>ParameterPort</code> (<code>RPortPrototype</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Speicher- und ROM-Optimierung:</strong> Ermöglicht das Teilen identischer Stützstellenvektoren (<code>AXIS_PTS</code>) zwischen mehreren Kennlinien/Kennfeldern zur Reduktion des ROM-Bedarfs im Steuergerät.\n</li><li><strong>A2L- / ASAM MCD-2 MC-Export:</strong> A2L-Generatoren nutzen diesen Pfad zwingend, um im Kalibrierfile für ein <code>CHARACTERISTIC</code> des Typs <code>MAP</code>/<code>CUBOID</code> einen <code>AXIS_DESCR</code> mit Verweis auf das separate <code>AXIS_PTS</code>-Objekt zu generieren (Referenz via <code>AXIS_PTS_REF</code>). Fehlt <code>SwCalprmRefProxy</code>, ist die A2L inkonsistent.\n</li><li><strong>RTE-API-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Der Zugriff auf die Achswerte erfolgt nicht implizit über den Kennfeldzugriff, sondern muss im SWC-Code separat über die vom RTE-Generator bereitgestellten Makros bzw. Funktionssignaturen bedient werden (z. B. <code>Rte_Prm_&lt;Port&gt;_&lt;Param&gt;()</code> bzw. Zugriff auf kalibrierbare ROM-Symbole).\n</li><li>Wenn <code>ParameterAccess</code> Achseneigenschaften über <code>swDataDefProps</code> überschreibt, muss der RTE-Generator sicherstellen, dass Konsistenz zu den Typdefinitionen (<code>ApplicationPrimitiveDataType</code> / <code>ImplementationDataType</code>) gewahrt bleibt.\n</li></ul>\n</li><li><strong>Modellierungs-Constraint:</strong> Da die Multiplizität von <code>+swCalprmRef</code> exakt <code>1</code> beträgt, darf eine als <code>SwAxisGrouped</code> typisierte Achse im XML/ARXML niemals ohne gültigen Proxy auf einen konkreten Stützstellen-<code>DataPrototype</code> belassen werden.\n</li></ul>"}], "trans": [{"from": "FIG-a53fe1bf9ebbdd17", "to": "FIG-ed55750d8c5a5ebf", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Kommentar-Notiz:</strong> Ein neuer Erläuterungsvermerk am Aggregationspfeil <code>+swCalprmRef</code> zwischen <code>SwAxisGrouped</code> und <code>SwCalprmRefProxy</code> wurde ergänzt („This aggregation cannot be set to 0..1 based on the non-mainstream schema generation instructions defined at the aggregation.“).\n</li></ul>"}, {"from": "FIG-ed55750d8c5a5ebf", "to": "FIG-a1724be6c3cdf4c5", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>ParameterAccess → SwDataDefProps:</strong> Die Aggregation <code>+swDataDefProps</code> [0..1] wurde um die UML-Eigenschaft <code>{redefines swDataDefProps}</code> erweitert (formale Redefinition der geerbten Assoziation).\n</li></ul>"}, {"from": "FIG-a1724be6c3cdf4c5", "to": "FIG-865b6a22e24bd8ca", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Kommentar-Notiz:</strong> Die Notiz zur Aggregation <code>+swCalprmRef</code> wurde vom unteren mittleren Bereich in den linken unteren Randbereich verschoben, wodurch sich die vertikale Bildabmessung verringert. Die Beschriftungsüberlappung bei <code>ParameterAccess</code> / <code>+swDataDefProps</code> wurde aufgelöst.\n</li></ul>"}]};
